        faqTag: 'Got Questions?',
        faqTitle: 'Frequently Asked Questions',
        faq1Q: 'How is my Carbon Footprint (kg CO₂e) calculated?',
        faq1A: 'CarbonTrack follows the Greenhouse Gas (GHG) Protocol standard. We multiply your reported activity metric (e.g., kilometers travelled, kWh consumed, or meal type) by scientifically verified emission factors from authoritative sources including the IPCC, EPA, and regional grid authorities.',
        faq2Q: 'What is the EcoScore and how does the 300–850 rating work?',
        faq2A: 'The EcoScore is a comprehensive index modeled on credit ratings. It evaluates three pillars: 1) Monthly Emission Performance (350 pts), 2) Logging Consistency & Streak (250 pts), and 3) Goal Adherence & Engagement (250 pts). Scores range from Needs Work (<550), Fair (551-670), Good (671-750), to Excellent (751-850).',
        faq3Q: 'Can CarbonTrack be used for corporate teams and organizations?',
        faq3A: 'Yes! CarbonTrack offers a dedicated Organisation Portal featuring employee engagement leaderboards, department-level carbon tracking, Scope 1/2/3 breakdown charts, and one-click PDF/CSV ESG compliance exports.',
        faq4Q: 'Are my logs and personal sustainability data private?',
        faq4A: 'Absolutely. Your data is encrypted in transit and at rest. If you join the community leaderboard, you can toggle Anonymous Mode at any time in Settings to mask your full name and profile details.',
        faq5Q: 'How do Carbon Offsets work in the Offset Hub?',
        faq5A: 'The Offset Hub allows users to support certified climate projects—such as certified reforestation, solar grid expansions, and methane capture. Each offset transaction is verified against recognized carbon registries (Gold Standard, Verra VCS) and directly credited to your portfolio.',
