          food: 'இறைச்சி மற்றும் பால் பொருட்கள் அதிக கார்பன் கால்தடத்தைக் கொண்டுள்ளன. வாரத்தில் சில உணவுகளுக்குப் பருப்பு மற்றும் காய்கறிகளைத் தேர்ந்தெடுக்கவும்.',
          shopping: 'புதிய பொருட்களை உற்பத்தி செய்ய அதிக கார்பன் தேவைப்படுகிறது. பொருட்களை பழுதுபார்த்து பயன்படுத்தவும் அல்லது இரண்டாம்கை பொருட்களை வாங்கவும்.',
          general: 'உயர் உமிழ்வு பகுதிகளைக் கண்டறியத் தினசரி பதிவுகளைப் பராமரித்து மாதாந்திர இலக்குகளை அமைக்கவும்.',
